INSERT INTO shared_exports (export_id, bundle_type, bundle_name, exported_content) 
VALUES ('SE-2024-EXT-OPS-001', 'external_ops_bundle', 'External Operations Bundle for Team Reproduction',
 (SELECT json_group_array(
    json_object(
      'filename', filename,
      'content', content,
      'notes', notes,
      'file_id', file_id
    )
  ) FROM config_files ORDER BY file_id));
